def generate_final():
    grid = [[0] * 30 for _ in range(30)]
    int_center = (13, 13)  # center of 23x23 interior

    # Draw 25x25 frame at rows 1-25, cols 1-25 (0-indexed)
    for r in range(1, 26):
        grid[r][1] = 5
        grid[r][25] = 5
    for c in range(1, 26):
        grid[1][c] = 5
        grid[25][c] = 5

    # Nested pattern in 23x23 interior at rows 2-24, cols 2-24
    int_max_dist = 11
    for d in range(1, int_max_dist + 1):
        color = 2 if (d % 2 == 1) else 5
        for rr in range(int_center[0] - d, int_center[0] + d + 1):
            for cc in range(int_center[1] - d, int_center[1] + d + 1):
                if (rr == int_center[0] - d or rr == int_center[0] + d or
                    cc == int_center[1] - d or cc == int_center[1] + d):
                    grid[rr][cc] = color

    return grid

